package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * Merges a person into another on the sheet; only a steward may, neither may be retired, and a person is not merged
 * into themselves. The merged person's claims move to the other, keeping their numbers and dates, each unbound from
 * any statement and listed after the other's claims in the order they were added. Their name and aliases become
 * aliases of the other; their patrons are added to the other's (not the other themselves, no repeats); anyone naming
 * them as patron names the other instead (no repeats); their pool memberships move to the other, the shares added
 * when the other is already a member, and so do their closed periods' totals. Their statements, holds, watchers and
 * contact are dropped, and they leave the sheet.
 */
@Service
public class PersonMerger {

    private final JdbcTemplate jdbc;
    private final People people;
    private final Roles roles;
    private final Audit audit;
    private final Rollup rollup;

    public PersonMerger(JdbcTemplate jdbc, People people, Roles roles, Audit audit, Rollup rollup) {
        this.jdbc = jdbc;
        this.people = people;
        this.roles = roles;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** Merges the person into the one with id {@code intoId}, writing nothing when it is refused. */
    public void merge(String sheet, String user, Person from, Long intoId) throws InvalidPersonException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidPersonException("Only a steward may merge people");
        }
        Person into = intoId == null ? null : people.find(sheet, intoId);
        if (into == null || into.id() == from.id()) {
            throw new InvalidPersonException("A person is merged into another person on the sheet");
        }
        if (from.retiredFrom() != null || into.retiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        Rollup.Snapshot before = rollup.take(sheet);
        long f = from.id();
        long t = into.id();

        // Claims, in the order they were added, each listed as the sheet's newest so they follow the other's.
        for (Long claim : jdbc.queryForList("SELECT id FROM claim WHERE sheet = ? AND person = ? ORDER BY id",
                Long.class, sheet, f)) {
            jdbc.update("UPDATE claim SET person = ?, stated = FALSE, stated_due = NULL, listed ="
                    + " (SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?) WHERE sheet = ? AND id = ?",
                    t, sheet, sheet, claim);
        }

        // Name and aliases become the other's aliases.
        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet = ? AND person_id = ?", t, sheet, f);
        jdbc.update("INSERT INTO person_alias (sheet, person_id, alias) VALUES (?, ?, ?)", sheet, t, from.name());

        // Patrons: the merged person's own, then everyone naming them.
        for (Long patron : jdbc.queryForList("SELECT patron_id FROM patron WHERE sheet = ? AND person_id = ?",
                Long.class, sheet, f)) {
            addPatron(sheet, t, patron);
        }
        for (Long person : jdbc.queryForList("SELECT person_id FROM patron WHERE sheet = ? AND patron_id = ?",
                Long.class, sheet, f)) {
            addPatron(sheet, person, t);
        }
        jdbc.update("DELETE FROM patron WHERE sheet = ? AND (person_id = ? OR patron_id = ?)", sheet, f, f);

        // Pool memberships, shares added where the other is already a member.
        for (Map<String, Object> m : jdbc.queryForList(
                "SELECT pool, share FROM pool_member WHERE sheet = ? AND person_id = ?", sheet, f)) {
            String pool = (String) m.get("POOL");
            BigDecimal share = (BigDecimal) m.get("SHARE");
            if (jdbc.update("UPDATE pool_member SET share = share + ? WHERE sheet = ? AND pool = ? AND person_id = ?",
                    share, sheet, pool, t) == 0) {
                jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet = ? AND pool = ? AND person_id = ?", t,
                        sheet, pool, f);
            }
        }
        jdbc.update("DELETE FROM pool_member WHERE sheet = ? AND person_id = ?", sheet, f);

        // Closed periods' totals follow the claims.
        for (Map<String, Object> p : jdbc.queryForList(
                "SELECT period, total FROM period_person_total WHERE sheet = ? AND person = ?", sheet, f)) {
            String period = (String) p.get("PERIOD");
            BigDecimal total = (BigDecimal) p.get("TOTAL");
            if (jdbc.update("UPDATE period_person_total SET total = total + ? WHERE sheet = ? AND period = ? AND person = ?",
                    total, sheet, period, t) == 0) {
                jdbc.update("UPDATE period_person_total SET person = ? WHERE sheet = ? AND period = ? AND person = ?",
                        t, sheet, period, f);
            }
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND person = ?", sheet, f);

        // Dropped with the person: statements, holds, watchers, grades and contact.
        jdbc.update("DELETE FROM statement WHERE sheet = ? AND person = ?", sheet, f);
        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", f);
        jdbc.update("DELETE FROM watch WHERE sheet = ? AND person_id = ?", sheet, f);
        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person WHERE sheet = ? AND id = ?", sheet, f);

        audit.record("PERSON_MERGED sheet=" + sheet + " by=" + user + " from=" + from.name() + " into=" + into.name());
        rollup.record(sheet, user, before);
    }

    /** Names the patron for the person, unless it is themselves or already named. */
    private void addPatron(String sheet, long person, long patron) {
        if (person == patron) {
            return;
        }
        Integer found = jdbc.queryForObject(
                "SELECT COUNT(*) FROM patron WHERE sheet = ? AND person_id = ? AND patron_id = ?", Integer.class, sheet,
                person, patron);
        if (found == null || found == 0) {
            jdbc.update("INSERT INTO patron (sheet, person_id, patron_id) VALUES (?, ?, ?)", sheet, person, patron);
        }
    }
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.alias.Aliases;
import net.officefloor.hq.app.claim.ClaimStatusChanger;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetArchive;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;

/**
 * Transfers a person to another sheet by id; only a steward may, a retired person may not be, nor to this sheet's own
 * id or an archived sheet, and a contact of theirs already on the other sheet refuses it. A name or alias of theirs
 * already on the other sheet (as names are compared) merges them into that person there, as a merge does: their claims
 * follow that person's, their name and aliases join that person's, and their grades, terms and contact are dropped (it is
 * refused when that person is retired, or their names are on more than one person there). Otherwise they arrive as
 * the other sheet's newest person, with this sheet as their origin, every grade (and its from-date), their terms,
 * contact and aliases, and their claims with their status, dates, notes, frozen figures, logs and comments, listed in
 * the order they were. Each claim that had a number takes the other sheet's next one, in the order the claims were
 * opened (by the sheet's today when each was opened, then the order they were added); a correction or split names its
 * claim's new number when that claim came along (none otherwise). Statement bindings are lost (the statement count
 * starts at 0) and references, locks and settle batches are not carried. They leave this sheet entirely: patron links,
 * pool memberships, holds, closed periods' totals, statements and watches are dropped.
 */
@Service
public class PersonTransferrer {

    private final JdbcTemplate jdbc;
    private final People people;
    private final Aliases aliases;
    private final Claims claims;
    private final ClaimStatusChanger changer;
    private final Roles roles;
    private final SheetArchive archive;
    private final Audit audit;
    private final Rollup rollup;

    public PersonTransferrer(JdbcTemplate jdbc, People people, Aliases aliases, Claims claims,
            ClaimStatusChanger changer, Roles roles, SheetArchive archive, Audit audit, Rollup rollup) {
        this.jdbc = jdbc;
        this.people = people;
        this.aliases = aliases;
        this.claims = claims;
        this.changer = changer;
        this.roles = roles;
        this.archive = archive;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** Transfers the person to the sheet {@code to}, writing nothing when it is refused. */
    public void transfer(String sheet, String user, Person person, String to) throws InvalidPersonException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidPersonException("Only a steward may transfer a person");
        }
        if (person.retiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be transferred");
        }
        if (to == null || to.isBlank() || to.equals(sheet)) {
            throw new InvalidPersonException("A person is transferred to another sheet");
        }
        if (archive.archived(to)) {
            throw new InvalidPersonException("An archived sheet cannot change");
        }
        long f = person.id();
        List<String> theirAliases = jdbc.queryForList(
                "SELECT alias FROM person_alias WHERE sheet = ? AND person_id = ? ORDER BY alias_key", String.class,
                sheet, f);
        List<String> names = new ArrayList<>(theirAliases);
        names.add(0, person.name());
        // A name or alias already on the other sheet names the person they are merged into there.
        Person into = null;
        for (String name : names) {
            Person found = people.findByName(to, name);
            if (found != null && into != null && found.id() != into.id()) {
                throw new InvalidPersonException("The names of " + person.name() + " are on more than one person on"
                        + " sheet " + to);
            }
            if (found != null) {
                into = found;
            }
        }
        if (into != null && into.retiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        if (into == null && person.contact() != null && people.contactTaken(to, person.contact(), null)) {
            throw new InvalidPersonException("The contact " + person.contact() + " is already on sheet " + to);
        }

        Rollup.Snapshot beforeHere = rollup.take(sheet);
        Rollup.Snapshot beforeThere = rollup.take(to);

        // The person, as the other sheet's newest, with their grades, terms, contact and aliases; or, merged, their
        // name and aliases joined to the other's.
        long t;
        if (into != null) {
            t = into.id();
            List<String> held = jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet = ? AND person_id = ?",
                    String.class, to, t);
            for (String name : names) {
                if (!name.equals(into.name()) && !held.contains(name)) {
                    aliases.add(to, t, name);
                    held.add(name);
                }
            }
        } else {
            t = arrive(sheet, f, to, theirAliases);
        }

        // Claims, in the order they were listed, each with its log, comments and void reason.
        List<String> claimColumns = columns("CLAIM");
        Map<Long, Long> moved = new LinkedHashMap<>();
        for (Long claim : jdbc.queryForList("SELECT id FROM claim WHERE sheet = ? AND person = ? ORDER BY listed, id",
                Long.class, sheet, f)) {
            long copy = copyClaim(claimColumns, sheet, claim, to, t);
            moved.put(claim, copy);
            jdbc.update("INSERT INTO claim_log (sheet, claim, status, by_user, on_date, due) SELECT ?, ?, status, by_user,"
                    + " on_date, due FROM claim_log WHERE sheet = ? AND claim = ? ORDER BY id", to, copy, sheet, claim);
            jdbc.update("INSERT INTO claim_comment (sheet, claim, by_user, on_date, text) SELECT ?, ?, by_user, on_date,"
                    + " text FROM claim_comment WHERE sheet = ? AND claim = ? ORDER BY id", to, copy, sheet, claim);
            jdbc.update("INSERT INTO claim_void (sheet, claim, reason) SELECT ?, ?, reason FROM claim_void"
                    + " WHERE sheet = ? AND claim = ?", to, copy, sheet, claim);
        }

        // Numbers: the other sheet's next, in the order the claims were opened (its today then, then the order added).
        Map<String, String> renumbered = new HashMap<>();
        if (!moved.isEmpty()) {
            String in = moved.keySet().stream().map(String::valueOf).collect(Collectors.joining(","));
            List<Map<String, Object>> numbered = jdbc.queryForList("SELECT c.id,"
                    + " COALESCE(c.period_number, CAST(c.number_on_sheet AS VARCHAR)) AS shown,"
                    + " COALESCE((SELECT MIN(l.on_date) FROM claim_log l WHERE l.sheet = c.sheet AND l.claim = c.id"
                    + " AND l.status = 'OPEN'), c.claimed_on) AS opened_on FROM claim c WHERE c.sheet = ? AND c.id IN ("
                    + in + ") AND (c.period_number IS NOT NULL OR c.number_on_sheet IS NOT NULL) ORDER BY opened_on, c.id",
                    sheet);
            for (Map<String, Object> row : numbered) {
                long copy = moved.get(((Number) row.get("ID")).longValue());
                var claim = changer.number(to, claims.find(to, copy));
                renumbered.put((String) row.get("SHOWN"),
                        claim.periodNumber() != null ? claim.periodNumber() : String.valueOf(claim.number()));
            }
            // A correction or split names its claim's new number, or none when that claim stayed behind.
            for (Map.Entry<Long, Long> e : moved.entrySet()) {
                Map<String, Object> row = jdbc.queryForMap("SELECT corrects, split_from FROM claim WHERE id = ?",
                        e.getKey());
                String corrects = (String) row.get("CORRECTS");
                String splitFrom = (String) row.get("SPLIT_FROM");
                jdbc.update("UPDATE claim SET corrects = ?, split_from = ? WHERE sheet = ? AND id = ?",
                        corrects == null ? null : renumbered.get(corrects),
                        splitFrom == null ? null : renumbered.get(splitFrom), to, e.getValue());
            }
        }

        // They leave this sheet entirely.
        if (!moved.isEmpty()) {
            String in = moved.keySet().stream().map(String::valueOf).collect(Collectors.joining(","));
            jdbc.update("DELETE FROM claim_log WHERE sheet = ? AND claim IN (" + in + ")", sheet);
            jdbc.update("DELETE FROM claim_comment WHERE sheet = ? AND claim IN (" + in + ")", sheet);
            jdbc.update("DELETE FROM claim_void WHERE sheet = ? AND claim IN (" + in + ")", sheet);
            jdbc.update("DELETE FROM claim WHERE sheet = ? AND id IN (" + in + ")", sheet);
        }
        jdbc.update("DELETE FROM person_alias WHERE sheet = ? AND person_id = ?", sheet, f);
        jdbc.update("DELETE FROM patron WHERE sheet = ? AND (person_id = ? OR patron_id = ?)", sheet, f, f);
        jdbc.update("DELETE FROM pool_member WHERE sheet = ? AND person_id = ?", sheet, f);
        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND person = ?", sheet, f);
        jdbc.update("DELETE FROM statement WHERE sheet = ? AND person = ?", sheet, f);
        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", f);
        jdbc.update("DELETE FROM watch WHERE sheet = ? AND person_id = ?", sheet, f);
        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person WHERE sheet = ? AND id = ?", sheet, f);

        audit.record("PERSON_TRANSFERRED sheet=" + sheet + " by=" + user + " name=" + person.name() + " to=" + to);
        rollup.record(sheet, user, beforeHere);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + user + " name=" + person.name() + " from=" + sheet);
        if (into != null) {
            audit.record("PERSON_MERGED sheet=" + to + " by=" + user + " from=" + person.name() + " into=" + into.name());
        }
        rollup.record(to, user, beforeThere);
    }

    /** Adds the person to the other sheet as its newest, with their grades, terms, contact, tags and aliases; returns their id. */
    private long arrive(String sheet, long f, String to, List<String> theirAliases) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO person (sheet, name, terms, contact, tags, list_position, origin) SELECT ?,"
                    + " name, terms, contact, tags, " + People.NEXT_POSITION + ", ? FROM person WHERE sheet = ? AND id = ?",
                    new String[] { "id" });
            ps.setString(1, to);
            ps.setString(2, to);
            ps.setString(3, sheet);
            ps.setString(4, sheet);
            ps.setLong(5, f);
            return ps;
        }, keys);
        long t = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) SELECT ?, grade, from_date FROM person_grade"
                + " WHERE person_id = ?", t, f);
        for (String alias : theirAliases) {
            aliases.add(to, t, alias);
        }
        return t;
    }

    /** The columns of the table a copy writes: all but its identity and generated ones. */
    private List<String> columns(String table) {
        return jdbc.queryForList("SELECT column_name FROM information_schema.columns WHERE table_schema = 'PUBLIC'"
                + " AND table_name = ? AND is_identity = 'NO' AND is_generated = 'NEVER' ORDER BY ordinal_position",
                String.class, table);
    }

    /**
     * Copies the claim to the person on the other sheet, listed as its newest, unbound from any statement, unnumbered
     * and with no reference, lock or settle batch; returns the copy's id.
     */
    private long copyClaim(List<String> columns, String sheet, long claim, String to, long person) {
        Map<String, String> set = Map.of("SHEET", "?", "PERSON", "?", "STATED", "FALSE", "STATED_DUE", "NULL",
                "NUMBER_ON_SHEET", "NULL", "PERIOD_NUMBER", "NULL", "REF", "NULL", "LOCKED_BY", "NULL", "BATCH", "NULL",
                "LISTED", "(SELECT COALESCE(MAX(l.listed), 0) + 1 FROM claim l WHERE l.sheet = ?)");
        String select = columns.stream().map((c) -> set.getOrDefault(c, "c." + c)).collect(Collectors.joining(", "));
        List<Object> args = new ArrayList<>();
        for (String c : columns) {
            switch (c) {
                case "SHEET", "LISTED" -> args.add(to);
                case "PERSON" -> args.add(person);
                default -> {
                }
            }
        }
        args.add(sheet);
        args.add(claim);
        String sql = "INSERT INTO claim (" + String.join(", ", columns) + ") SELECT " + select
                + " FROM claim c WHERE c.sheet = ? AND c.id = ?";
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(sql, new String[] { "id" });
            for (int i = 0; i < args.size(); i++) {
                ps.setObject(i + 1, args.get(i));
            }
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.hq.app.sheet.SheetState;
import net.officefloor.hq.app.sheet.SheetStates;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Takes a statement of the person: records their due-total now (late charges included), binds each of their
 * counting claims to the figure it has now (without its late charge) and unbinds the rest. The due-total is n/a
 * when their grade has no rate on the sheet's today, unless a
 * counting claim has a figure apart from it (settled, bound, or at another grade in force on its date): then it is the figures there are.
 * <p>
 * Taken as of a date on or before the sheet's today, it is made from the sheet as it stood at the end of that date
 * (every change made while the sheet's today was on or before it, none after), with that date for the sheet's today
 * in every figure; it binds the claims of theirs that counted then to their figures then and unbinds the rest. A date
 * after the sheet's today is refused, and so is one on which the person was not on the sheet.
 */
public class TakeStatement {
    public void take(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @RequestBody StatementRequest request, @Val Person person, Claims claims,
            Statements statements, SheetClock clock, SheetStates states, Audit audit, Rollup rollup)
            throws InvalidPersonException {
        LocalDate today = clock.today(sheet);
        LocalDate asOf = asOf(request);
        if (asOf != null && asOf.isAfter(today)) {
            throw new InvalidPersonException("A statement cannot be taken as of a date after the sheet's today");
        }
        LocalDate on = asOf == null ? today : asOf;
        SheetState state = on.equals(today) ? states.now(sheet) : states.at(sheet, on);
        Person then = state == null ? null : state.person(person.id(), on);
        if (then == null) {
            throw new InvalidPersonException(person.name() + " was not on the sheet on " + on);
        }
        Rollup.Snapshot before = rollup.take(sheet);
        List<Rate> sheetRates = state.rates();
        Dated floor = state.floorDated();
        Late late = state.late(on);
        List<Claim> past = state.claimsOf(person.id(), on);
        boolean na = Rate.on(sheetRates, then.grade(), on) == null
                && past.stream().noneMatch((c) -> then.counts(c) && then.figureApartFrom(c, on, sheetRates, floor));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : past) {
            if (then.counts(claim)) {
                // The statement binds the rate figure (before the floor); the late charge keeps following the sheet's today.
                bound.put(claim.id(), claim.figure(sheetRates, then.gradeOn(claim.date()), floor, late.rounding(claim)));
                BigDecimal due = claim.due(sheetRates, then.gradeOn(claim.date()), floor, late);
                total = due == null ? total : total.add(due);
            }
        }
        Map<Long, Claim> mine = claims.list(sheet).stream().filter((c) -> c.person() == person.id())
                .collect(Collectors.toMap(Claim::id, Function.identity()));
        for (Claim claim : mine.values()) {
            if (bound.containsKey(claim.id())) {
                claims.setStated(sheet, claim.id(), true, bound.get(claim.id()));
            } else if (claim.stated()) {
                claims.setStated(sheet, claim.id(), false, null);
            }
        }
        BigDecimal dueTotal = na ? null : Settings.capped(total, state.capOn(on));
        statements.add(sheet, person.id(), dueTotal, today, asOf);
        audit.record("STATEMENT sheet=" + sheet + " by=" + user + " name=" + person.name() + " due-total="
                + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + bound.size()
                + (asOf == null ? "" : " asof=" + asOf));
        rollup.record(sheet, user, before);
    }

    /** The as-of date the request gives, or null when it gives none. */
    private static LocalDate asOf(StatementRequest request) throws InvalidPersonException {
        String asof = request == null || request.asof() == null ? "" : request.asof().trim();
        try {
            return asof.isEmpty() ? null : LocalDate.parse(asof);
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a valid as-of date: " + asof);
        }
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The statements taken of the people on each sheet. */
@Repository
public class Statements {

    private final JdbcTemplate jdbc;

    public Statements(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Per person on the sheet with a statement: the count, and the last one's due-total and date (the date it was taken as of, else the sheet's today then). */
    public List<StatementSummary> list(String sheet) {
        return jdbc.query("""
                SELECT s.person, c.taken, s.due_total, COALESCE(s.as_of, s.taken_on) AS stated_on FROM statement s
                JOIN (SELECT person, COUNT(*) AS taken, MAX(id) AS last FROM statement WHERE sheet = ? GROUP BY person) c
                  ON s.id = c.last
                ORDER BY s.person""", (rs, i) -> {
            BigDecimal due = rs.getBigDecimal("due_total");
            return new StatementSummary(rs.getLong("person"), rs.getInt("taken"),
                    due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    rs.getDate("stated_on").toLocalDate().toString());
        }, sheet);
    }

    /**
     * Records a statement of the person: their due-total (null when n/a), taken on the date, as of a date (null when
     * taken now).
     */
    public void add(String sheet, long person, BigDecimal dueTotal, LocalDate takenOn, LocalDate asOf) {
        jdbc.update("INSERT INTO statement (sheet, person, due_total, taken_on, as_of) VALUES (?, ?, ?, ?, ?)", sheet,
                person, dueTotal, Date.valueOf(takenOn), asOf == null ? null : Date.valueOf(asOf));
    }

    /** The person's last statement, if they have one. */
    public Optional<Taken> last(String sheet, long person) {
        return jdbc.query("SELECT id, due_total FROM statement WHERE sheet = ? AND person = ? ORDER BY id DESC LIMIT 1",
                (rs, i) -> new Taken(rs.getLong("id"), rs.getBigDecimal("due_total")), sheet, person)
                .stream().findFirst();
    }

    /** Removes the statement. */
    public void delete(String sheet, long id) {
        jdbc.update("DELETE FROM statement WHERE sheet = ? AND id = ?", sheet, id);
    }

    /** A statement taken: its id and due-total (null when n/a). */
    public record Taken(long id, BigDecimal dueTotal) {
    }
}

