package net.officefloor.hq.app.statement;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * A steward cancels the person's last statement: the claims it bound are live again (none goes back to a figure an
 * earlier statement bound) and the statement before it, if any, is the last one shown. Refuses anyone else, or a
 * person with no statement.
 */
public class CancelStatement {
    public void cancel(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            Claims claims, Statements statements, Roles roles, Audit audit, Rollup rollup) throws InvalidPersonException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidPersonException("Only a steward cancels a statement");
        }
        Statements.Taken last = statements.last(sheet, person.id())
                .orElseThrow(() -> new InvalidPersonException(person.name() + " has no statement to cancel"));
        Rollup.Snapshot before = rollup.take(sheet);
        claims.unbindPerson(sheet, person.id());
        statements.delete(sheet, last.id());
        audit.record("STATEMENT_CANCELLED sheet=" + sheet + " by=" + user + " name=" + person.name() + " due-total="
                + (last.dueTotal() == null ? "n/a" : last.dueTotal().toPlainString()));
        rollup.record(sheet, user, before);
    }
}
-- A claim bound by its person's last statement: stated is true while bound, and stated_due is the figure it
-- was bound to (null when its grade had no rate then). A statement rebinds every claim of the person.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(15, 2);
-- The statements taken of a person: their due-total then (null when n/a) and the sheet's today then.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet     VARCHAR(200)   NOT NULL,
    person    BIGINT         NOT NULL REFERENCES person (id),
    due_total DECIMAL(15, 2),
    taken_on  DATE           NOT NULL
);
CREATE INDEX statement_sheet ON statement (sheet, person, id);
-- A statement may be taken as of a date on or before the sheet's today: as_of is that date (null when it was taken
-- now), shown as the statement's date in place of taken_on.
ALTER TABLE statement ADD COLUMN as_of DATE;
-- The sheet as it stood when its today moved from from_today to to_today: every change made while the sheet's today
-- was from_today counts in it, and none made after. The state is the people, claims, rates and settings then (JSON).
CREATE TABLE sheet_state (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet      VARCHAR(200) NOT NULL,
    from_today DATE         NOT NULL,
    to_today   DATE         NOT NULL,
    state      CLOB         NOT NULL
);
CREATE INDEX sheet_state_sheet ON sheet_state (sheet, id);
