s=s.replace('''import net.officefloor.hq.app.sheet.SheetArchive;
''','''import net.officefloor.hq.app.sheet.SheetArchive;
import net.officefloor.hq.app.statement.Statements;
''')
s=s.replace(''' * claim's new number when that claim came along (none otherwise). Statement bindings are lost (the statement count
 * starts at 0) and references, locks and settle batches are not carried. They leave this sheet entirely: patron links,
 * pool memberships, holds, closed periods' totals, statements and watches are dropped.''',''' * claim's new number when that claim came along (none otherwise). Each claim keeps any figure a statement bound it to,
 * and their statements go with them: the receiving person's statement count is their own plus these, and their last
 * statement stays theirs (or, having none, becomes the transferred person's). References, locks and settle batches are
 * not carried. They leave this sheet entirely: patron links, pool memberships, holds, closed periods' totals and
 * watches are dropped.''')
s=s.replace('''    private final Rollup rollup;

    public PersonTransferrer(JdbcTemplate jdbc, People people, Aliases aliases, Claims claims,
            ClaimStatusChanger changer, Roles roles, SheetArchive archive, Audit audit, Rollup rollup) {''','''    private final Rollup rollup;
    private final Statements statements;

    public PersonTransferrer(JdbcTemplate jdbc, People people, Aliases aliases, Claims claims,
            ClaimStatusChanger changer, Roles roles, SheetArchive archive, Audit audit, Rollup rollup,
            Statements statements) {''')
s=s.replace('''        this.rollup = rollup;
    }''','''        this.rollup = rollup;
        this.statements = statements;
    }''')
s=s.replace('''        // They leave this sheet entirely.
''','''        // Statements go with them, the receiving person's last staying theirs.
        statements.move(sheet, f, to, t);

        // They leave this sheet entirely.
''')
s=s.replace('''        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND person = ?", sheet, f);
        jdbc.update("DELETE FROM statement WHERE sheet = ? AND person = ?", sheet, f);
''','''        jdbc.update("DELETE FROM period_person_total WHERE sheet = ? AND person = ?", sheet, f);
''')
s=s.replace('''     * Copies the claim to the person on the other sheet, listed as its newest, unbound from any statement, unnumbered
     * and with no reference, lock or settle batch; returns the copy's id.''','''     * Copies the claim to the person on the other sheet, listed as its newest, keeping any figure a statement bound it
     * to, unnumbered and with no reference, lock or settle batch; returns the copy's id.''')
s=s.replace('''Map.of("SHEET", "?", "PERSON", "?", "STATED", "FALSE", "STATED_DUE", "NULL",
                "NUMBER_ON_SHEET"''','''Map.of("SHEET", "?", "PERSON", "?", "NUMBER_ON_SHEET"''')
open(p,'w').write(s)
